REPLACE:
// Match a colon with optional whitespace then a type name starting with uppercase (and possibly containing '), but not followed by another colon (avoid ::), and not inside string or comment
		pattern: /(:\s*)\b[A-Z][\w\']*\b/,
		lookbehind: true,
		alias: 'class-name'
	},
	'preprocessor': {
		pattern: /^[^\r\n\S]*#.*/m,
		alias: 'property',
		inside: {
			'directive': {
				pattern: /(\s*#)\b(?:else|endif|if|light|line|nowarn)\b/,
				lookbehind: true,
				alias: 'keyword'
			}
		}
	}
});
